param([string]$PythonExe="",[string]$RepoRoot="D:\AssertionForge-main1",[string]$RelayUrl="https://api.highwayapi.ai/openai/chat/completions",[string]$GptModel="gpt-5.4",[string]$ClaudeModel="claude-opus-4-8",[int]$Seed=20260721)
$ErrorActionPreference="Stop";if(-not $PythonExe){$p=Join-Path $env:USERPROFILE ".cache\codex-runtimes\codex-primary-runtime\dependencies\python\python.exe";if(Test-Path $p){$PythonExe=$p}else{$PythonExe=(Get-Command python -ErrorAction Stop).Source}};Set-Location -LiteralPath $RepoRoot
$names=@("OPENAI_API_KEY","ANTHROPIC_API_KEY","MULTIMODEL_OPENAI_BASE_URL","MULTIMODEL_OPENAI_MODEL","MULTIMODEL_CLAUDE_PROVIDER","MULTIMODEL_CLAUDE_BASE_URL","MULTIMODEL_CLAUDE_MODEL","MULTIMODEL_SEED","PYTHONHASHSEED");$old=@{};foreach($n in $names){$old[$n]=[Environment]::GetEnvironmentVariable($n,"Process")};$secure=Read-Host "Highway API key" -AsSecureString;$ptr=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure)
try{$key=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr);$env:OPENAI_API_KEY=$key;$env:ANTHROPIC_API_KEY=$key;$env:MULTIMODEL_OPENAI_BASE_URL=$RelayUrl;$env:MULTIMODEL_OPENAI_MODEL=$GptModel;$env:MULTIMODEL_CLAUDE_PROVIDER="openai_compatible";$env:MULTIMODEL_CLAUDE_BASE_URL=$RelayUrl;$env:MULTIMODEL_CLAUDE_MODEL=$ClaudeModel;$env:MULTIMODEL_SEED="$Seed";$env:PYTHONHASHSEED="$Seed";& $PythonExe src/run_end_to_end_pipeline.py --seed $Seed --model GPT --model Claude;if($LASTEXITCODE-ne 0){throw "End-to-end formal pipeline failed"}}
finally{if($ptr-ne[IntPtr]::Zero){[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr)};$key=$null;foreach($n in $names){[Environment]::SetEnvironmentVariable($n,$old[$n],"Process")}}
